namespace Sonrisa.EventAlertSystem.Api.Domain;

public enum NotificationChannel
{
    Email,
    Slack
}

namespace Sonrisa.EventAlertSystem.Api.Domain;

public enum NotificationDeliveryStatus
{
    Pending,
    Processing,
    Recorded,
    Sent,
    Failed
}

namespace Sonrisa.EventAlertSystem.Api.Domain;

public sealed class AlertRule
{
    public int Id { get; set; }
    public required string UserId { get; set; }
    public required string Name { get; set; }
    public string? Category { get; set; }
    public bool IsEnabled { get; set; } = true;
    public bool IsDeleted { get; set; }
    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow;
    public ICollection<AlertRuleKeyword> Keywords { get; set; } = new List<AlertRuleKeyword>();
    public ICollection<AlertRuleChannel> Channels { get; set; } = new List<AlertRuleChannel>();
    public ICollection<NotificationDelivery> Deliveries { get; set; } = new List<NotificationDelivery>();
}

namespace Sonrisa.EventAlertSystem.Api.Domain;

public sealed class AlertRuleKeyword
{
    public int Id { get; set; }
    public int AlertRuleId { get; set; }
    public required string Keyword { get; set; }
    public AlertRule AlertRule { get; set; } = null!;
}

namespace Sonrisa.EventAlertSystem.Api.Domain;

public sealed class AlertRuleChannel
{
    public int Id { get; set; }
    public int AlertRuleId { get; set; }
    public NotificationChannel Channel { get; set; }
    public AlertRule AlertRule { get; set; } = null!;
}

namespace Sonrisa.EventAlertSystem.Api.Domain;

public sealed class Event
{
    public int Id { get; set; }
    public required string Fingerprint { get; set; }
    public required string Category { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public DateTime OccurredAtUtc { get; set; }
    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
    public ICollection<NotificationDelivery> Deliveries { get; set; } = new List<NotificationDelivery>();
}

namespace Sonrisa.EventAlertSystem.Api.Domain;

public sealed class NotificationDelivery
{
    public int Id { get; set; }
    public int EventId { get; set; }
    public int AlertRuleId { get; set; }
    public NotificationChannel Channel { get; set; }
    public NotificationDeliveryStatus Status { get; set; } = NotificationDeliveryStatus.Pending;
    public int AttemptCount { get; set; }
    public DateTime? NextAttemptAtUtc { get; set; }
    public string? LastError { get; set; }
    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow;
    public DateTime? SentAtUtc { get; set; }
    public Event Event { get; set; } = null!;
    public AlertRule AlertRule { get; set; } = null!;
}

using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Api.Application;

public sealed class AlertMatchingService
{
    public IReadOnlyList<AlertRule> Match(Event eventItem, IEnumerable<AlertRule> rules)
    {
        return rules
            .Where(rule => rule.IsEnabled && !rule.IsDeleted)
            .Where(rule => CategoryMatches(rule, eventItem))
            .Where(rule => KeywordsMatch(rule, eventItem))
            .ToArray();
    }

    private static bool CategoryMatches(AlertRule rule, Event eventItem)
    {
        return string.IsNullOrWhiteSpace(rule.Category)
            || string.Equals(rule.Category, eventItem.Category, StringComparison.OrdinalIgnoreCase);
    }

    private static bool KeywordsMatch(AlertRule rule, Event eventItem)
    {
        var keywords = rule.Keywords
            .Select(keyword => keyword.Keyword)
            .Where(keyword => !string.IsNullOrWhiteSpace(keyword));

        return !keywords.Any()
            || keywords.Any(keyword => eventItem.Title.Contains(keyword, StringComparison.OrdinalIgnoreCase)
                || eventItem.Description.Contains(keyword, StringComparison.OrdinalIgnoreCase));
    }
}

namespace Sonrisa.EventAlertSystem.Api.Application;

public sealed record DemoIdentity(string Id, string DisplayName, string Role);

public sealed class DemoIdentityRegistry
{
    private static readonly IReadOnlyList<DemoIdentity> Identities =
    [
        new("demo-user", "Demo User", "User"),
        new("demo-admin", "Demo Administrator", "Admin")
    ];

    public IReadOnlyList<DemoIdentity> GetAll() => Identities;

    public bool TryGet(string id, out DemoIdentity? identity)
    {
        identity = Identities.FirstOrDefault(candidate =>
            string.Equals(candidate.Id, id, StringComparison.OrdinalIgnoreCase));
        return identity is not null;
    }
}

using Microsoft.EntityFrameworkCore;
using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Api.Infrastructure.Persistence;

public sealed class EventAlertDbContext(DbContextOptions<EventAlertDbContext> options) : DbContext(options)
{
    public DbSet<AlertRule> AlertRules => Set<AlertRule>();
    public DbSet<AlertRuleKeyword> AlertRuleKeywords => Set<AlertRuleKeyword>();
    public DbSet<AlertRuleChannel> AlertRuleChannels => Set<AlertRuleChannel>();
    public DbSet<Event> Events => Set<Event>();
    public DbSet<NotificationDelivery> NotificationDeliveries => Set<NotificationDelivery>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(EventAlertDbContext).Assembly);
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Api.Infrastructure.Persistence.Configurations;

public sealed class AlertRuleConfiguration : IEntityTypeConfiguration<AlertRule>
{
    public void Configure(EntityTypeBuilder<AlertRule> builder)
    {
        builder.ToTable("AlertRules");
        builder.HasKey(rule => rule.Id);
        builder.Property(rule => rule.UserId).HasMaxLength(100).IsRequired();
        builder.Property(rule => rule.Name).HasMaxLength(120).IsRequired();
        builder.Property(rule => rule.Category).HasMaxLength(100);
        builder.Property(rule => rule.CreatedAtUtc).IsRequired();
        builder.Property(rule => rule.UpdatedAtUtc).IsRequired();

        builder.HasMany(rule => rule.Keywords)
            .WithOne(keyword => keyword.AlertRule)
            .HasForeignKey(keyword => keyword.AlertRuleId)
            .OnDelete(DeleteBehavior.Cascade);
        builder.HasMany(rule => rule.Channels)
            .WithOne(channel => channel.AlertRule)
            .HasForeignKey(channel => channel.AlertRuleId)
            .OnDelete(DeleteBehavior.Cascade);
        builder.HasMany(rule => rule.Deliveries)
            .WithOne(delivery => delivery.AlertRule)
            .HasForeignKey(delivery => delivery.AlertRuleId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Api.Infrastructure.Persistence.Configurations;

public sealed class AlertRuleKeywordConfiguration : IEntityTypeConfiguration<AlertRuleKeyword>
{
    public void Configure(EntityTypeBuilder<AlertRuleKeyword> builder)
    {
        builder.ToTable("AlertRuleKeywords");
        builder.HasKey(keyword => keyword.Id);
        builder.Property(keyword => keyword.Keyword).HasMaxLength(100).UseCollation("NOCASE").IsRequired();
        builder.HasIndex(keyword => new { keyword.AlertRuleId, keyword.Keyword }).IsUnique();
    }
}

