using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Api.Infrastructure.Persistence.Configurations;

public sealed class EventConfiguration : IEntityTypeConfiguration<Event>
{
    public void Configure(EntityTypeBuilder<Event> builder)
    {
        builder.ToTable("Events");
        builder.HasKey(eventItem => eventItem.Id);
        builder.Property(eventItem => eventItem.Fingerprint).HasMaxLength(64).IsRequired();
        builder.HasIndex(eventItem => eventItem.Fingerprint).IsUnique();
        builder.Property(eventItem => eventItem.Category).HasMaxLength(100).IsRequired();
        builder.Property(eventItem => eventItem.Title).HasMaxLength(300).IsRequired();
        builder.Property(eventItem => eventItem.Description).HasMaxLength(4000).IsRequired();
        builder.Property(eventItem => eventItem.OccurredAtUtc).IsRequired();
        builder.Property(eventItem => eventItem.CreatedAtUtc).IsRequired();
        builder.HasMany(eventItem => eventItem.Deliveries)
            .WithOne(delivery => delivery.Event)
            .HasForeignKey(delivery => delivery.EventId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Api.Infrastructure.Persistence.Configurations;

public sealed class NotificationDeliveryConfiguration : IEntityTypeConfiguration<NotificationDelivery>
{
    public void Configure(EntityTypeBuilder<NotificationDelivery> builder)
    {
        builder.ToTable("NotificationDeliveries");
        builder.HasKey(delivery => delivery.Id);
        builder.Property(delivery => delivery.Channel).HasConversion<string>().HasMaxLength(20).IsRequired();
        builder.Property(delivery => delivery.Status).HasConversion<string>().HasMaxLength(20).IsRequired();
        builder.Property(delivery => delivery.LastError).HasMaxLength(2000);
        builder.Property(delivery => delivery.CreatedAtUtc).IsRequired();
        builder.Property(delivery => delivery.UpdatedAtUtc).IsRequired();
        builder.HasIndex(delivery => new { delivery.EventId, delivery.AlertRuleId, delivery.Channel }).IsUnique();
    }
}

using Sonrisa.EventAlertSystem.Api.Application;
using Sonrisa.EventAlertSystem.Api.Domain;

namespace Sonrisa.EventAlertSystem.Tests;

public sealed class AlertMatchingServiceTests
{
    private readonly AlertMatchingService _service = new();

    [Fact]
    public void CategoryOnlyRule_MatchesEqualCategory()
    {
        var rule = CreateRule(category: "Weather");

        var matches = _service.Match(CreateEvent(category: "Weather"), [rule]);

        Assert.Single(matches);
    }

    [Fact]
    public void KeywordOnlyRule_MatchesTitleOrDescription()
    {
        var rule = CreateRule(keywords: ["flood"]);

        var matches = _service.Match(CreateEvent(description: "A flood warning was issued"), [rule]);

        Assert.Single(matches);
    }

    [Fact]
    public void CategoryAndKeywordRule_RequiresBothConditions()
    {
        var rule = CreateRule(category: "Weather", keywords: ["flood"]);

        var categoryOnlyEvent = CreateEvent(category: "Weather", title: "Rain expected");
        var keywordOnlyEvent = CreateEvent(category: "News", title: "Flood warning");

        Assert.Empty(_service.Match(categoryOnlyEvent, [rule]));
        Assert.Empty(_service.Match(keywordOnlyEvent, [rule]));
        Assert.Single(_service.Match(CreateEvent(category: "Weather", title: "Flood warning"), [rule]));
    }

    [Fact]
    public void MultipleKeywords_UseOrMatching()
    {
        var rule = CreateRule(keywords: ["flood", "wildfire"]);

        var matches = _service.Match(CreateEvent(title: "Wildfire evacuation"), [rule]);

        Assert.Single(matches);
    }

    [Fact]
    public void CategoryAndKeywordComparisons_AreCaseInsensitive()
    {
        var rule = CreateRule(category: "WEATHER", keywords: ["FLOOD"]);

        var matches = _service.Match(CreateEvent(category: "weather", title: "Flood warning"), [rule]);

        Assert.Single(matches);
    }

    [Fact]
    public void EmptyConditions_MatchAnyEvent()
    {
        var rule = CreateRule(category: " ");

        var matches = _service.Match(CreateEvent(category: "Markets"), [rule]);

        Assert.Single(matches);
    }

    [Fact]
    public void DisabledAndLogicallyDeletedRules_DoNotMatch()
    {
        var disabledRule = CreateRule() with { };
        disabledRule.IsEnabled = false;
        var deletedRule = CreateRule();
        deletedRule.IsDeleted = true;

        var matches = _service.Match(CreateEvent(), [disabledRule, deletedRule]);

        Assert.Empty(matches);
    }

    [Fact]
    public void Match_ReturnsEveryMatchingRule()
    {
        var rules = new[]
        {
            CreateRule(category: "Weather"),
            CreateRule(keywords: ["storm"]),
            CreateRule(category: "Markets")
        };

        var matches = _service.Match(CreateEvent(category: "Weather", title: "Storm approaching"), rules);

        Assert.Equal(2, matches.Count);
        Assert.Contains(rules[0], matches);
        Assert.Contains(rules[1], matches);
    }

    private static AlertRule CreateRule(string? category = null, string[]? keywords = null)
    {
        var rule = new AlertRule { UserId = "demo-user", Name = "Test rule", Category = category };
        foreach (var keyword in keywords ?? [])
        {
            rule.Keywords.Add(new AlertRuleKeyword { Keyword = keyword });
        }

        return rule;
    }

    private static Event CreateEvent(
        string category = "Weather",
        string title = "Clear skies",
        string description = "Forecast update")
    {
        return new Event
        {
            Fingerprint = Guid.NewGuid().ToString("N"),
            Category = category,
            Title = title,
            Description = description,
            OccurredAtUtc = DateTime.UtcNow
        };
    }
}

using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Sonrisa.EventAlertSystem.Api.Domain;
using Sonrisa.EventAlertSystem.Api.Infrastructure.Persistence;

namespace Sonrisa.EventAlertSystem.Tests;

public sealed class PersistenceConstraintTests
{
    [Fact]
    public async Task EventFingerprint_MustBeUnique()
    {
        await using var connection = await CreateDatabaseConnection();
        await using var context = CreateContext(connection);
        await context.Database.EnsureCreatedAsync();

        context.Events.Add(CreateEvent("duplicate-fingerprint"));
        await context.SaveChangesAsync();
        context.Events.Add(CreateEvent("duplicate-fingerprint"));

        await Assert.ThrowsAsync<DbUpdateException>(() => context.SaveChangesAsync());
    }

    [Fact]
    public async Task DeliveryEventRuleAndChannelCombination_MustBeUnique()
    {
        await using var connection = await CreateDatabaseConnection();
        await using var context = CreateContext(connection);
        await context.Database.EnsureCreatedAsync();

        var eventItem = CreateEvent("delivery-event");
        var rule = new AlertRule { UserId = "demo-user", Name = "Test rule" };
        context.AddRange(eventItem, rule);
        await context.SaveChangesAsync();

        context.NotificationDeliveries.Add(CreateDelivery(eventItem.Id, rule.Id));
        await context.SaveChangesAsync();
        context.NotificationDeliveries.Add(CreateDelivery(eventItem.Id, rule.Id));

        await Assert.ThrowsAsync<DbUpdateException>(() => context.SaveChangesAsync());
    }

    private static async Task<SqliteConnection> CreateDatabaseConnection()
    {
        var connection = new SqliteConnection("Data Source=:memory:");
        await connection.OpenAsync();
        return connection;
    }

    private static EventAlertDbContext CreateContext(SqliteConnection connection)
    {
        var options = new DbContextOptionsBuilder<EventAlertDbContext>()
            .UseSqlite(connection)
            .Options;
        return new EventAlertDbContext(options);
    }

    private static Event CreateEvent(string fingerprint)
    {
        return new Event
        {
            Fingerprint = fingerprint,
            Category = "Weather",
            Title = "Storm warning",
            Description = "A storm warning was issued",
            OccurredAtUtc = DateTime.UtcNow
        };
    }

    private static NotificationDelivery CreateDelivery(int eventId, int ruleId)
    {
        return new NotificationDelivery
        {
            EventId = eventId,
            AlertRuleId = ruleId,
            Channel = NotificationChannel.Email
        };
    }
}

